<?php
/** Catalog and admin operations: two scoped tasks and source-bound native guidance. */
defined('ABSPATH') || exit;
final class WCJ_Catalog_Admin_Workspace {
 public static function data(){return require __DIR__.'/catalog-admin-groups.php';}
 public static function groups(){return self::data()['groups'];}
 public static function edition(){return WCJ_Toolbar_Categories_Job::edition();}
 public static function allowed($id){$core=WCJ_Job_Store::core();return current_user_can('manage_woocommerce')&&$core&&isset($core->all_modules[$id])&&(!function_exists('wcj_is_module_allowed_by_allowlist')||wcj_is_module_allowed_by_allowlist($id))&&(!wcj_is_module_enabled('modules_by_user_roles')||wcj_check_modules_by_user_roles($id));}
 public static function raw($key){global $wpdb;$r=$wpdb->get_row($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name=%s",$key),ARRAY_A);if($wpdb->last_error){throw new RuntimeException('Saved catalog settings could not be read.');}return $r?(string)$r['option_value']:null;}
 public static function flag($value,$default='no'){return null===$value?'Not set (default: '.('yes'===$default?'On':'Off').')':('yes'===$value?'Saved: On':('no'===$value?'Saved: Off':'Saved value needs full settings'));}
 private static function count($value){return null===$value?'One by default':(is_string($value)&&preg_match('/\A(?:0|[1-9][0-9]{0,8})\z/D',$value)?$value.' saved; fields shown in full settings':'Saved count needs full settings');}
 public static function url(){return admin_url('admin.php?page=wcj-catalog-admin');}
 public static function link($url,$label){return '<a target="_blank" rel="noopener noreferrer" href="'.esc_url($url).'">'.esc_html($label.' (new tab)').'</a>';}
 public static function native_url($g){if(!self::allowed($g['module'])){return '';}$url='product'===$g['surface']?admin_url('edit.php?post_type=product'):admin_url(wcj_admin_tab_url().'&section='.$g['module'].'&active_tab='.$g['native_tab']);return $url;}
 public static function entry(){foreach(self::groups() as $g){if(self::allowed($g['module'])){echo '<p><a href="'.esc_url(self::url()).'">Catalog &amp; Admin Tools: toolbar preferences and selected-product cost fill</a></p>';return;}}}
 public static function help($module='',$pick=array()){$edition=self::edition();foreach(self::groups() as $g){if(($module&&$module!==$g['module'])||($pick&&!in_array($g['id'],$pick,true))||!self::allowed($g['module'])){continue;}echo '<article class="wcj-catalog-group" data-catalog-admin-group="'.esc_attr($g['id']).'"><h3>'.esc_html($g['label']).'</h3><p>'.esc_html($g['context']).'</p>';if(isset($g['badge'])){echo '<p class="wcj-catalog-caution">'.esc_html($g['badge']).'</p>';}echo '<p>'.self::link(self::native_url($g),'product'===$g['surface']?'Choose a product in the existing editor':'Full settings').' | '.self::link($g['guide'],'Guide: '.$g['label']);if(isset($g['tool'])&&'yes'===self::raw('wcj_'.$g['module'].'_enabled')){echo ' | '.self::link(admin_url('admin.php?page=wcj-tools&tab='.$g['tool'].'&wcj_tools_nonce='.wp_create_nonce('wcj_tools')),'Open existing tool');}echo '</p><details><summary>Fields and actions covered</summary><ul>';foreach($g['members'][$edition] as $m){echo '<li>'.esc_html($m['label'].($m['locked']?' (locked in Free)':'')).($m['hint']?' <span class="description">'.esc_html($m['hint']).'</span>':'').'</li>';}echo '</ul></details></article>';}}
 public static function screen_help(){if(!current_user_can('manage_woocommerce')){return;}$page=$_GET['page']??'';$section=$_GET['section']??'';$tab=$_GET['tab']??'';$active=$_GET['active_tab']??'';if(!is_string($page)||!is_string($section)||!is_string($tab)||!is_string($active)){return;}$pick=array();
  if('wcj-plugins'===$page){foreach(self::groups() as $g){if($g['module']===$section&&(!$active||$active===$g['native_tab'])){$pick[]=$g['id'];}}}
  elseif('wcj-tools'===$page){foreach(self::groups() as $g){if(isset($g['tool'])&&$tab===$g['tool']){$pick[]=$g['id'];}}}
  else{$screen=get_current_screen();if($screen){if('product'===$screen->post_type&&'post'===$screen->base){$pick[]='purchase-data-product-fields';}elseif('product'===$screen->post_type&&'edit'===$screen->base){$pick=array('product-list-columns','product-list-order','purchase-data-product-columns');}elseif(('shop_order'===$screen->post_type&&'edit'===$screen->base)||'woocommerce_page_wc-orders'===$screen->id){$pick=array('order-list-columns','order-list-status','order-list-order','purchase-data-order-columns');}}}
  $pick=array_values(array_filter($pick,static function($id){foreach(self::groups() as $g){if($g['id']===$id){return self::allowed($g['module']);}}return false;}));if(!$pick){return;}echo '<div class="notice notice-info"><p><a href="'.esc_url(self::url()).'">Catalog &amp; Admin Tools</a>. Help opens separately without changing this screen.</p><details><summary>These controls: effects and guidance</summary>';self::help('',$pick);echo '</details></div>';
 }
 public static function summaries($module){$rows=array('Module'=>self::flag(self::raw('wcj_'.$module.'_enabled')));$free='free'===self::edition();
  $flags=array('admin_bar'=>array('wcj_admin_bar_wc_enabled'=>array('WooCommerce toolbar menu','yes'),'wcj_admin_bar_wc_list_cats'=>array('Category links','no'),'wcj_admin_bar_wc_list_tags'=>array('Tag links','no')),'admin_orders_list'=>array('wcj_order_admin_list_custom_columns_enabled'=>array('Custom columns','no'),'wcj_order_admin_list_multiple_status_enabled'=>array('Multiple-status views','no')),'admin_products_list'=>array('wcj_products_admin_list_custom_columns_enabled'=>array('Custom columns','no'),'wcj_products_admin_list_columns_order_enabled'=>array('Column ordering','no')),'product_bulk_meta_editor'=>array('wcj_product_bulk_meta_editor_check_if_exists'=>array('Hide rows without the chosen metadata','no'),'wcj_product_bulk_meta_editor_add_variations'=>array('Include variations in table','no')),'purchase_data'=>array('wcj_purchase_price_enabled'=>array('Product cost component','yes'),'wcj_purchase_price_extra_enabled'=>array('Extra expense component','yes'),'wcj_purchase_price_affiliate_commission_enabled'=>array('Commission component','no')),'sku'=>array('wcj_sku_new_products_generate_enabled'=>array('Automatic new-product generation','yes'),'wcj_sku_generate_on_save'=>array('Variation save generation','no'),'wcj_sku_allow_duplicates_enabled'=>array('Duplicate SKUs allowed','no')));
  foreach($flags[$module]??array() as $key=>$pair){$rows[$pair[0]]=self::flag(self::raw($key),$pair[1]);}
  $counts=array('admin_orders_list'=>array('Custom column count'=>'wcj_orders_list_custom_columns_total_number','Status preset count'=>'wcj_order_admin_list_multiple_status_presets_total_number'),'admin_products_list'=>array('Custom column count'=>'wcj_products_admin_list_custom_columns_total_number'),'purchase_data'=>array('Custom cost field count'=>'wcj_purchase_data_custom_price_fields_total_number'));
  foreach($counts[$module]??array() as $label=>$key){$rows[$label]=$free?'One under the Free edition rule':self::count(self::raw($key));}
  if('bulk_price_converter'===$module){$rows['Price change scope']='Chosen in the existing tool; no product prices read here';$rows['Category / pretty-price controls']=$free?'Locked in Free':'Available in the existing paid tool';}
  if('product_bulk_meta_editor'===$module){$rows['Variation selection rights']=$free?'Locked in Free; a saved switch is not proof of access':'Paid variation selection available';$rows['Metadata values']='Not loaded until deliberately selected in the existing tool';}
  if('sku'===$module){$raw=self::raw('wcj_sku_number_generation');$labels=array('product_id'=>'Product ID','sequential'=>'Sequential','hash_crc32'=>'Pseudorandom hash','hashids'=>'Hashids');$rows['Number method']=$free?'Product ID under the Free edition rule':(null===$raw?'Product ID by default':($labels[$raw]??'Saved choice needs full settings'));$rows['Categories and counters']='Dynamic fields stay in full settings; no counters advanced here';}
  return $rows;
 }
 public static function register(){if(current_user_can('manage_woocommerce')){add_submenu_page('woocommerce','Catalog & Admin Tools','Catalog & Admin Tools','manage_woocommerce','wcj-catalog-admin',array(__CLASS__,'render'));}}
 private static function assets(){wp_enqueue_style('wcj-catalog-admin',wcj_plugin_url().'/assets/css/admin/wcj-catalog-admin-workspace.css',array(),'1.0');wp_enqueue_script('wcj-catalog-admin',wcj_plugin_url().'/assets/js/admin/wcj-catalog-admin-workspace.js',array(),'1.0',true);$nonces=array('toolbar'=>array(),'cost'=>array());foreach(WCJ_Toolbar_Categories_Job::OPS as $op){$nonces['toolbar'][$op]=wp_create_nonce('wcj_toolbar_categories_'.$op);}foreach(WCJ_Missing_Cost_Job::OPS as $op){$nonces['cost'][$op]=wp_create_nonce('wcj_missing_cost_'.$op);}wp_localize_script('wcj-catalog-admin','wcjCatalogAdminWorkspace',array('url'=>admin_url('admin-ajax.php'),'nonces'=>$nonces));}
 public static function render(){if(!current_user_can('manage_woocommerce')){wp_die('Ask an administrator for access.');}self::assets();echo '<div class="wrap wcj-catalog-workspace"><h1>Catalog &amp; Admin Tools</h1><p>Keep display preferences separate from product-data changes. This workspace does not enable modules, run the old bulk tools or preview saved shortcodes. Existing site behavior can still run as WordPress loads.</p>';try{foreach(array('view'=>'Change what you see','data'=>'Change product data') as $section=>$label){echo '<section class="wcj-catalog-lane"><h2>'.esc_html($label).'</h2>';if('view'===$section&&self::allowed('admin_bar')){self::toolbar_form();}if('data'===$section&&self::allowed('purchase_data')){self::cost_form();}$seen=array();foreach(self::groups() as $g){$module=$g['module'];if($g['section']!==$section||isset($seen[$module])||!self::allowed($module)){continue;}$seen[$module]=true;$labels=array('admin_bar'=>'Admin Bar','admin_orders_list'=>'Admin Orders List','admin_products_list'=>'Admin Products List','bulk_price_converter'=>'Bulk Price Converter','product_bulk_meta_editor'=>'Product Bulk Meta Editor','purchase_data'=>'Purchase Data / Cost of Goods','sku'=>'SKU');$rows=self::summaries($module);echo '<details class="wcj-catalog-module" id="wcj-catalog-'.esc_attr($module).'"><summary><strong>'.esc_html($labels[$module]).'</strong> <span>'.esc_html($rows['Module']).'</span></summary><dl class="wcj-catalog-current">';foreach($rows as $key=>$value){echo '<div><dt>'.esc_html($key).'</dt><dd>'.esc_html($value).'</dd></div>';}echo '</dl>';self::help($module);echo '</details>';}echo '</section>';}}catch(Throwable $e){echo '<p role="alert">'.esc_html($e->getMessage()).'</p>';}echo '</div>';}
 private static function toolbar_form(){$t=self::data()['tasks']['toolbar'];echo '<form class="wcj-toolbar-task"><h3>'.esc_html($t['label']).'</h3><p>'.esc_html($t['scope']).'</p><p>'.esc_html($t['blocked']).'</p><p class="description">'.esc_html($t['supported']).'</p><details><summary>Installation details</summary><p>'.esc_html($t['supported_details']).'</p></details><label><input type="checkbox" name="categories" disabled> Show category links</label><p class="wcj-toolbar-saved"></p><p class="wcj-toolbar-status" role="status" aria-live="polite">Loading saved preference...</p><button class="button button-primary" type="submit" disabled>Save preference</button> <button class="button wcj-toolbar-restore" type="button" disabled>Restore previous setting</button> <button class="button wcj-toolbar-reload" type="button">Discard draft and reload</button><details><summary>Recovery and scope</summary><p>'.esc_html($t['restore']).'</p><p>Only drafts in this form are tracked. Edits in another tab are checked again when saving, not monitored live.</p></details><p>'.self::link(admin_url(wcj_admin_tab_url().'&section=admin_bar&active_tab=admin_bar_general_options_tab'),'Full toolbar settings').' | '.self::link(self::task_guide('admin_bar',$t['anchor']),'Toolbar setup guide').'</p></form>';}
 private static function task_guide($module,$anchor){foreach(self::groups() as $g){if($g['module']===$module){return explode('#',$g['guide'])[0].'#'.$anchor;}}return '';}
 private static function cost_form(){$t=self::data()['tasks']['cost'];echo '<form class="wcj-cost-task"><h3>'.esc_html($t['label']).'</h3><p>'.esc_html($t['scope']).'</p><p class="wcj-catalog-caution">'.esc_html($t['consequence']).'</p><p>'.esc_html($t['prerequisite']).'</p><p class="description">'.esc_html($t['supported']).'</p><details><summary>Installation details</summary><p>'.esc_html($t['supported_details']).'</p></details><label for="wcj-cost-ids">'.esc_html($t['input']).'</label><textarea id="wcj-cost-ids" name="ids" rows="3" maxlength="1024" placeholder="For example: 101, 102, 103" aria-describedby="wcj-cost-scope"></textarea><p id="wcj-cost-scope">Only explicitly simple products you may edit. No catalog search, variations or default-all selection.</p><button class="button" type="submit">Preview selected products</button> <button class="button button-primary wcj-cost-execute" type="button" disabled>Fill 0 product costs</button> <button class="button wcj-cost-results" type="button">Reload saved results</button> <button class="button wcj-cost-undo" type="button" disabled>Undo unchanged filled costs</button><p class="wcj-cost-status" role="status" aria-live="polite">Preview has not run. No costs have been changed by this form.</p><div class="wcj-cost-output" tabindex="-1"></div><details><summary>Amount format, partial results and Undo</summary><p>'.esc_html($t['decimal']).'</p><p>'.esc_html($t['calculation']).'</p><p>Preview expires after ten minutes. Each eligible item is checked again and saved separately; earlier items can remain saved if another item fails. Reload saved results if the response is lost.</p><p>'.esc_html($t['undo']).'</p><p>'.esc_html($t['limits']).'</p></details><p>'.self::link(self::task_guide('purchase_data',$t['anchor']),'Fill missing costs guide').' | '.self::link(admin_url(wcj_admin_tab_url().'&section=purchase_data&active_tab=wcj_cost_of_goods_tool_tab'),'Different action: legacy whole-catalog import').'</p></form>';}
}
add_action('admin_menu',array('WCJ_Catalog_Admin_Workspace','register'),99);
add_action('admin_notices',array('WCJ_Catalog_Admin_Workspace','screen_help'),43);
